"""Screenshot-inspired Quotex layout; page content remains generated separately."""
from expanded import GROUPS

def apply_design(page):
    start=page.index('<header>');end=page.index('</header>',start)+len('</header>')
    menu=''.join(f'<a href="#{group}" data-title="{group}">{en}</a>' for group,en,_,children in GROUPS)
    header='''<header class="site-header"><a class="brand" href="#home" aria-label="Quotex home"><span class="brand-icon" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none"><path d="M5 26 16 6h11L16 26H5Z" fill="currentColor"/><path d="m4 17 7-12h9l-7 12H4Z" fill="currentColor" opacity=".55"/></svg></span>quotex<span class="brand-dot">.</span></a><div class="header-actions"><a class="outline-button outbound login-link" data-ui="login">Log in</a><a class="button small outbound" data-ui="open">Explore platform ↗</a><label class="sr-only" for="language">Language</label><select id="language"><option value="en">EN · English</option><option value="hi">HI · हिन्दी</option></select><button class="outline-button menu-toggle" type="button" id="menu-toggle" aria-expanded="false" aria-controls="site-menu"><span aria-hidden="true">☰</span><span data-ui="menu">Menu</span></button></div><nav id="site-menu" class="menu-panel" aria-label="Sections" hidden>'''+menu+'''</nav></header>'''
    page=page[:start]+header+page[end:]
    start=page.index('<section class="hero">');end=page.index('<nav class="topic-nav"',start)
    hero='''<section class="hero screenshot-hero"><div class="hero-glow" aria-hidden="true"></div><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span><span data-ui="eyebrow">A clearer way to explore the markets</span></div><h1 data-title="hero"></h1><div class="hero-lead" data-copy="hero"></div><div class="cta-row"><a class="button outbound" data-ui="start">Explore Quotex ↗</a><a class="outline-button" href="#practice"><span class="play-symbol" aria-hidden="true"></span><span data-ui="how">How it works</span></a></div><div class="hero-promo"><div><span data-ui="promo">YOUR PROMO CODE</span><strong>bingame</strong><small data-ui="promoCheck">Check current offer terms</small></div><button type="button" id="copy" data-ui="copy" aria-live="polite">Copy</button></div><div class="hero-benefits"><div><span aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path d="m5 18 13-13M7 5h11v11" stroke="currentColor" stroke-width="1.5"/></svg></span><small data-ui="benefitStart">Account essentials</small></div><div><span aria-hidden="true">◇</span><small data-ui="benefitRisk">Risk awareness</small></div><div><span aria-hidden="true">▤</span><small data-ui="benefitDemo">Demo learning</small></div><div><span aria-hidden="true">◎</span><small data-ui="benefitMobile">Made for mobile</small></div></div></div><div class="hero-art"><img src="hero-trader.png" width="1536" height="1024" alt="" fetchpriority="high" decoding="async"><div class="art-orbit" aria-hidden="true"></div><div class="info-card demo-card"><span data-ui="cardDemo">PRACTICE WORKSPACE</span><strong>DEMO</strong><p data-ui="cardLearn">Understand the controls before a decision.</p><svg viewBox="0 0 150 45" aria-hidden="true"><path d="M3 38 18 25 32 31 47 14 61 23 77 10 94 24 110 8 130 16 147 4" fill="none" stroke="currentColor" stroke-width="3"/></svg></div><div class="info-card control-card"><span data-ui="cardRisk">TRADE RISK</span><strong data-ui="cardControl">Stay in control</strong><p data-ui="cardPlan">Review the possible loss before you act.</p><div class="status-dots" aria-hidden="true"><i></i><i></i><i></i></div></div><span class="art-caption" data-ui="artCaption">Concept illustration · not live market data</span></div></section><div class="feature-strip popular-strip"><span class="search-symbol" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><circle cx="10" cy="10" r="6" stroke="currentColor" stroke-width="2"/><path d="m15 15 6 6" stroke="currentColor" stroke-width="2"/></svg></span><span data-ui="popular">Popular topics</span><a href="#account">Quotex login</a><a href="#installation">Quotex app</a><a href="#practice">Quotex demo</a><a href="#payments" data-ui="withdrawal">Withdrawals</a></div>'''
    return page[:start]+hero+page[end:]

